DO $admission$ DECLARE item text;who text;BEGIN
 IF current_user<>'postgres' OR current_setting('server_version_num')::integer NOT BETWEEN 170000 AND 179999
 THEN RAISE EXCEPTION 'correction_writer_owner_version_required';END IF;
 -- Check conflicts first so the full-bundle late-refusal fixture reaches this component.
 FOREACH item IN ARRAY ARRAY['ca_correction_request_intents_v1','ca_correction_request_intents_v1_pkey',
   'ca_correction_request_intents_v1_ledger_id_key'] LOOP
  IF to_regclass('public.'||item) IS NOT NULL OR to_regtype('public.'||item) IS NOT NULL
  THEN RAISE EXCEPTION 'correction_writer_contract_preexists' USING DETAIL='public.'||item;END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='ca_correction_intent_immutable_v1')
 THEN RAISE EXCEPTION 'correction_writer_contract_preexists' USING DETAIL='public.ca_correction_intent_immutable_v1';END IF;
 FOREACH who IN ARRAY ARRAY['anon','authenticated','service_role'] LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=who AND NOT rolsuper AND NOT rolcreaterole AND NOT rolcreatedb AND NOT rolreplication)
   OR pg_has_role(who,'postgres','USAGE') OR pg_has_role(who,'postgres','SET')
   OR has_schema_privilege(who,'public','CREATE')
   OR (who<>'service_role' AND (EXISTS(SELECT 1 FROM pg_roles WHERE rolname=who AND rolbypassrls)
      OR pg_has_role(who,'service_role','USAGE') OR pg_has_role(who,'service_role','SET')))
  THEN RAISE EXCEPTION 'correction_writer_unsafe_api_role' USING DETAIL=who;END IF;
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_accounting_run_observation_v1(uuid,text,uuid,timestamptz,timestamptz)')
   AND proowner='postgres'::regrole AND prosecdef AND md5(prosrc)='6d9debfc281c2e425e5cfc4ec2a35dcc')
 THEN RAISE EXCEPTION 'correction_writer_requires_preserved35';END IF;
END $admission$;

