  target:=to_regprocedure(expected->>'signature');
  IF target IS NULL OR NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=target AND prokind='f' AND pg_get_userbyid(proowner)=expected->>'owner')
  THEN RAISE EXCEPTION 'correction_writer_dependency_preimage_changed' USING DETAIL=expected->>'signature';END IF;
  IF expected ? 'full_definition_md5' THEN
   IF md5(pg_get_functiondef(target)) IS DISTINCT FROM expected->>'full_definition_md5'
   THEN RAISE EXCEPTION 'correction_writer_dependency_preimage_changed' USING DETAIL=expected->>'signature';END IF;
  ELSE
   IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=target AND md5(prosrc)=expected->>'source_md5'
       AND prosecdef=(expected->>'security_definer')::boolean AND NOT proretset
       AND prolang=(SELECT oid FROM pg_language WHERE lanname=expected->>'language')
       AND provolatile::text=expected->>'volatility' AND proparallel::text=expected->>'parallel'
       AND proisstrict=(expected->>'strict')::boolean AND proleakproof=(expected->>'leakproof')::boolean
       AND pronargdefaults=(expected->>'argument_defaults')::integer
       AND COALESCE(to_jsonb(proargnames),'[]'::jsonb)=expected->'argument_names'
       AND pg_get_function_result(oid)=expected->>'result')
   THEN RAISE EXCEPTION 'correction_writer_dependency_preimage_changed' USING DETAIL=expected->>'signature';END IF;
   SELECT jsonb_agg(lower(replace(v,' ','')) ORDER BY lower(replace(v,' ',''))) INTO actual
     FROM pg_proc p,LATERAL unnest(p.proconfig)v WHERE p.oid=target;
   IF actual IS DISTINCT FROM expected->'normalized_config'
   THEN RAISE EXCEPTION 'correction_writer_dependency_preimage_changed' USING DETAIL=expected->>'signature';END IF;
  END IF;
  SELECT jsonb_agg(jsonb_build_object('role',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,
    'privilege',x.privilege_type,'grantable',x.is_grantable)
    ORDER BY CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,x.privilege_type,x.is_grantable)
   INTO actual FROM pg_proc p,LATERAL aclexplode(COALESCE(p.proacl,acldefault('f',p.proowner)))x WHERE p.oid=target;
  IF actual IS DISTINCT FROM expected->'grants'
  THEN RAISE EXCEPTION 'correction_writer_dependency_access_changed' USING DETAIL=expected->>'signature';END IF;
  FOREACH who IN ARRAY ARRAY['anon','authenticated','service_role'] LOOP
   SELECT EXISTS(SELECT 1 FROM jsonb_array_elements(expected->'grants')g WHERE g->>'role' IN(who,'PUBLIC') AND g->>'privilege'='EXECUTE') INTO allowed;
   IF has_function_privilege(who,target,'EXECUTE') IS DISTINCT FROM allowed
   THEN RAISE EXCEPTION 'correction_writer_dependency_access_changed' USING DETAIL=who||':'||(expected->>'signature');END IF;
  END LOOP;
 END LOOP;
END $functions$;

