,"force_rls":false,"constraints":[{"name":"ca_ledger_write_failures_pkey","type":"p","deferred":false,"validated":true,"deferrable":false,"definition":"PRIMARY KEY (id)"}],"effective_access":[{"role":"anon","delete":false,"insert":false,"select":true,"update":false,"trigger":true,"truncate":false},{"role":"authenticated","delete":false,"insert":false,"select":true,"update":false,"trigger":true,"truncate":false},{"role":"service_role","delete":true,"insert":true,"select":true,"update":true,"trigger":true,"truncate":true}]}]$incident_expected$::jsonb) LOOP
  target:=to_regclass(expected->>'name');
  IF NOT EXISTS(SELECT 1 FROM pg_class c WHERE c.oid=target AND pg_get_userbyid(c.relowner)=expected->>'owner'
    AND c.relkind::text=expected->>'kind' AND c.relrowsecurity=(expected->>'rls')::boolean
    AND c.relforcerowsecurity=(expected->>'force_rls')::boolean AND NOT c.relispartition)
    OR EXISTS(SELECT 1 FROM pg_inherits WHERE target IN(inhparent,inhrelid))
  THEN RAISE EXCEPTION 'correction_writer_relation_preimage_changed' USING DETAIL=expected->>'name';END IF;
  SELECT jsonb_agg(a::text ORDER BY a::text) INTO actual FROM pg_class c,LATERAL unnest(c.relacl)a WHERE c.oid=target;
  IF actual IS DISTINCT FROM NULLIF(expected->'acl','null'::jsonb)
  THEN RAISE EXCEPTION 'correction_writer_relation_access_changed' USING DETAIL=expected->>'name';END IF;
  SELECT jsonb_agg(jsonb_build_object('name',a.attname,'number',a.attnum,'type',format_type(a.atttypid,a.atttypmod),
   'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity,'generated',a.attgenerated,'acl',a.attacl,
   'effective_access',(SELECT jsonb_agg(jsonb_build_object('role',api,'select',has_column_privilege(api,target,a.attnum,'SELECT'),
    'insert',has_column_privilege(api,target,a.attnum,'INSERT'),'update',has_column_privilege(api,target,a.attnum,'UPDATE')) ORDER BY api)
    FROM unnest(ARRAY['anon','authenticated','service_role'])api)) ORDER BY a.attnum)
   INTO actual FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
   WHERE a.attrelid=target AND a.attnum>0 AND NOT a.attisdropped;
  IF actual IS DISTINCT FROM expected->'columns' THEN RAISE EXCEPTION 'correction_writer_columns_changed' USING DETAIL=expected->>'name';END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('name',k.conname,'type',k.contype,'definition',pg_get_constraintdef(k.oid,false),
   'validated',k.convalidated,'deferrable',k.condeferrable,'deferred',k.condeferred) ORDER BY k.conname),'[]'::jsonb)
   INTO actual FROM pg_constraint k WHERE k.conrelid=target;
  IF actual IS DISTINCT FROM expected->'constraints' THEN RAISE EXCEPTION 'correction_writer_constraints_changed' USING DETAIL=expected->>'name';END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('name',ci.relname,'definition',pg_get_indexdef(i.indexrelid),
   'valid',i.indisvalid,'ready',i.indisready) ORDER BY ci.relname),'[]'::jsonb)
   INTO actual FROM pg_index i JOIN pg_class ci ON ci.oid=i.indexrelid WHERE i.indrelid=target;
  IF actual IS DISTINCT FROM expected->'indexes' THEN RAISE EXCEPTION 'correction_writer_indexes_changed' USING DETAIL=expected->>'name';END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('name',t.tgname,'definition',pg_get_triggerdef(t.oid,false),
   'enabled',t.tgenabled) ORDER BY t.tgname),'[]'::jsonb) INTO actual FROM pg_trigger t WHERE t.tgrelid=target AND NOT t.tgisinternal;
  IF actual IS DISTINCT FROM expected->'triggers' THEN RAISE EXCEPTION 'correction_writer_triggers_changed' USING DETAIL=expected->>'name';END IF;
  SELECT COALESCE(jsonb_agg(to_jsonb(p) ORDER BY p.policyname),'[]'::jsonb) INTO actual FROM pg_policies p
   WHERE p.schemaname='public' AND p.tablename=split_part(expected->>'name','.',2);
  IF actual IS DISTINCT FROM expected->'policies' THEN RAISE EXCEPTION 'correction_writer_policies_changed' USING DETAIL=expected->>'name';END IF;
  SELECT jsonb_agg(jsonb_build_object('role',api,'select',has_table_privilege(api,target,'SELECT'),
   'insert',has_table_privilege(api,target,'INSERT'),'update',has_table_privilege(api,target,'UPDATE'),
   'delete',has_table_privilege(api,target,'DELETE'),'truncate',has_table_privilege(api,target,'TRUNCATE'),
   'trigger',has_table_privilege(api,target,'TRIGGER')) ORDER BY api) INTO actual
   FROM unnest(ARRAY['anon','authenticated','service_role'])api;
  IF actual IS DISTINCT FROM expected->'effective_access' THEN RAISE EXCEPTION 'correction_writer_relation_access_changed' USING DETAIL=expected->>'name';END IF;
 END LOOP;
 -- Component34's private provenance remains private, under the same owner.
 target:='public.accounting_correction_documents'::regclass;
 IF NOT EXISTS(SELECT 1 FROM pg_class WHERE oid=target AND relkind='r' AND relowner='postgres'::regrole AND relrowsecurity AND NOT relforcerowsecurity)
  OR EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=target)
  OR EXISTS(SELECT 1 FROM unnest(ARRAY['anon','authenticated','service_role'])api
   CROSS JOIN unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER','MAINTAIN'])priv
   WHERE has_table_privilege(api,target,priv))
  OR EXISTS(SELECT 1 FROM unnest(ARRAY['anon','authenticated','service_role'])api
   CROSS JOIN unnest(ARRAY['SELECT','INSERT','UPDATE','REFERENCES'])priv WHERE has_any_column_privilege(api,target,priv))
 THEN RAISE EXCEPTION 'correction_writer_document_authority_changed';END IF;
END $incident_catalog$;

-- BEGIN exact owner private-intent.sql (SHA256 69d5778c84a084062b46f28e31f84b22231a9fe7599c01dcfcaf278d7f42f693).
-- SOURCE CANDIDATE ONLY. Not registered with any activation loader.
-- Apply only in the same admitted transaction as the successor definition,
-- after exact predecessor and complete catalog/ACL guards have passed.
-- No IF NOT EXISTS: never adopt an unrelated preexisting relation.
CREATE TABLE public.ca_correction_request_intents_v1 (
  linkage_key text PRIMARY KEY,
  ledger_id uuid NOT NULL UNIQUE,
  request_intent jsonb NOT NULL CHECK (
    jsonb_typeof(request_intent) = 'object'
    AND request_intent->>'version' = '1'
  ),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
ALTER TABLE public.ca_correction_request_intents_v1 OWNER TO postgres;
ALTER TABLE public.ca_correction_request_intents_v1 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.ca_correction_request_intents_v1 FROM PUBLIC, anon, authenticated, service_role;

CREATE FUNCTION public.ca_correction_intent_immutable_v1()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog AS $function$
BEGIN
  RAISE EXCEPTION 'correction_intent_is_immutable';
END;
$function$;
ALTER FUNCTION public.ca_correction_intent_immutable_v1() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.ca_correction_intent_immutable_v1() FROM PUBLIC, anon, authenticated, service_role;
CREATE TRIGGER ca_correction_intent_immutable_v1
  BEFORE UPDATE OR DELETE OR TRUNCATE ON public.ca_correction_request_intents_v1
  FOR EACH STATEMENT EXECUTE FUNCTION public.ca_correction_intent_immutable_v1();

-- No FK to a potentially partitioned ledger's UUID alone. The qualified
-- writer binds both IDs atomically; replay verifies the retained ledger ID.
-- No backfill, app policy, public reader, or service INSERT grant.
-- END exact owner private-intent.sql.

-- BEGIN exact owner successor-definition.sql (SHA256 6200b53066002ccf11640baf9c39e6e296a9577ad30106225c67290f8d88ed7b).
-- SOURCE CANDIDATE ONLY; requires coordinated protected admission.
CREATE OR REPLACE FUNCTION public.fn_ca_post_correction(p_from_type text, p_from_entity uuid, p_to_type text, p_to_entity uuid, p_amount numeric, p_reason text, p_incident_id uuid DEFAULT NULL::uuid, p_write_failure_id bigint DEFAULT NULL::bigint, p_club_id uuid DEFAULT NULL::uuid, p_union_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_mgmt boolean := false;
  v_key text;
  v_id uuid;
  v_existing uuid;
  v_intent jsonb;
  v_prior_intent jsonb;
  v_prior_ledger uuid;
  v_expected_ref text;
  v_event_id bigint;
  v_event_detail jsonb;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    SELECT EXISTS (
      SELECT 1 FROM public.ca_incident_recipients r WHERE r.user_id = v_uid AND r.active
      UNION ALL
      SELECT 1 FROM public.profiles p WHERE p.id = v_uid AND p.role IN ('admin','god')
    ) INTO v_mgmt;
    IF NOT v_mgmt THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'management_only');
    END IF;
  END IF;

  IF p_amount IS NULL OR p_amount::text IN ('NaN', 'Infinity', '-Infinity')
     OR p_amount <= 0 OR p_amount <> round(p_amount, 2) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'amount_must_be_positive_cents');
  END IF;
  IF COALESCE(btrim(p_reason), '') = '' OR length(p_reason) < 20 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'a_correction_needs_a_real_reason');
  END IF;

  -- THE LINKAGE RULE: no correction without a live reference to what it fixes.
  IF p_incident_id IS NULL AND p_write_failure_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'linkage_required_incident_or_write_failure');
  END IF;
  IF p_incident_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.ca_drift_incidents WHERE id = p_incident_id) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'incident_not_found');
  END IF;
  IF p_write_failure_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.ca_ledger_write_failures WHERE id = p_write_failure_id) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'write_failure_not_found');
  END IF;

  v_key := 'correction:' || COALESCE('lwf:' || p_write_failure_id::text,
                                     'inc:' || p_incident_id::text);

  -- Version 1 compares full typed intent, not the truncated ledger projection.
  -- JSONB object key order / numeric scale are semantic; SQL NULL metadata is
  -- deliberately distinct from JSON null and from an explicit empty object.
  v_intent := jsonb_build_object(
    'version', 1, 'actor_uid', v_uid,
    'from_type', p_from_type, 'from_entity', p_from_entity,
    'to_type', p_to_type, 'to_entity', p_to_entity,
    'amount', p_amount, 'reason', p_reason,
    'incident_id', p_incident_id, 'write_failure_id', p_write_failure_id,
    'club_id', p_club_id, 'union_id', p_union_id,
    'metadata_sql_null', p_metadata IS NULL, 'metadata', p_metadata);

  SELECT id INTO v_existing FROM public.chip_ledger WHERE idempotency_key = v_key;
  IF v_existing IS NOT NULL THEN
    SELECT request_intent, ledger_id INTO v_prior_intent, v_prior_ledger
      FROM public.ca_correction_request_intents_v1 WHERE linkage_key = v_key;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'legacy_correction_intent_unavailable');
    END IF;
    IF v_prior_ledger IS DISTINCT FROM v_existing THEN
      RAISE EXCEPTION 'correction_intent_ledger_mismatch';
    END IF;
    IF v_prior_intent IS DISTINCT FROM v_intent THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'correction_intent_conflict');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.chip_ledger l
      WHERE l.id = v_existing AND l.idempotency_key = v_key
        AND l.status IS NOT DISTINCT FROM 'posted'
        AND l.performed_by IS NOT DISTINCT FROM
          COALESCE(v_uid, '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid)
        AND l.from_type IS NOT DISTINCT FROM p_from_type
        AND l.from_entity_id IS NOT DISTINCT FROM p_from_entity
        AND l.to_type IS NOT DISTINCT FROM p_to_type
        AND l.to_entity_id IS NOT DISTINCT FROM p_to_entity
        AND l.amount IS NOT DISTINCT FROM p_amount
        AND l.category IS NOT DISTINCT FROM 'correction'
        AND l.club_id IS NOT DISTINCT FROM p_club_id
        AND l.union_id IS NOT DISTINCT FROM p_union_id
        AND l.description IS NOT DISTINCT FROM left(p_reason, 900)
        AND l.metadata IS NOT DISTINCT FROM
          (COALESCE(p_metadata, '{}'::jsonb)
           || jsonb_build_object('incident_id', p_incident_id,
                                 'write_failure_id', p_write_failure_id,
                                 'posted_via', 'fn_ca_post_correction'))) THEN
      RAISE EXCEPTION 'correction_ledger_projection_mismatch';
    END IF;
    RETURN jsonb_build_object('ok', true, 'replayed', true, 'ledger_id', v_existing);
  END IF;

  INSERT INTO public.chip_ledger
    (performed_by, from_type, from_entity_id, to_type, to_entity_id,
     amount, category, club_id, union_id, description, idempotency_key, metadata)
  VALUES
    (COALESCE(v_uid, '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid),
     p_from_type, p_from_entity, p_to_type, p_to_entity,
     p_amount, 'correction', p_club_id, p_union_id,
     left(p_reason, 900), v_key,
     COALESCE(p_metadata, '{}'::jsonb)
       || jsonb_build_object('incident_id', p_incident_id,
                             'write_failure_id', p_write_failure_id,
                             'posted_via', 'fn_ca_post_correction'))
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN RAISE EXCEPTION 'correction_ledger_insert_missing'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.chip_ledger l
    WHERE l.id = v_id AND l.idempotency_key = v_key
      AND l.status IS NOT DISTINCT FROM 'posted'
      AND l.performed_by IS NOT DISTINCT FROM
        COALESCE(v_uid, '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid)
      AND l.from_type IS NOT DISTINCT FROM p_from_type
      AND l.from_entity_id IS NOT DISTINCT FROM p_from_entity
      AND l.to_type IS NOT DISTINCT FROM p_to_type
      AND l.to_entity_id IS NOT DISTINCT FROM p_to_entity
      AND l.amount IS NOT DISTINCT FROM p_amount
      AND l.category IS NOT DISTINCT FROM 'correction'
      AND l.club_id IS NOT DISTINCT FROM p_club_id
      AND l.union_id IS NOT DISTINCT FROM p_union_id
      AND l.description IS NOT DISTINCT FROM left(p_reason, 900)
      AND l.metadata IS NOT DISTINCT FROM
        (COALESCE(p_metadata, '{}'::jsonb)
         || jsonb_build_object('incident_id', p_incident_id,
                               'write_failure_id', p_write_failure_id,
                               'posted_via', 'fn_ca_post_correction'))) THEN
    RAISE EXCEPTION 'correction_ledger_projection_mismatch';
  END IF;

  IF p_incident_id IS NOT NULL THEN
    -- Lock the same incident row the following UPDATE already owns. Freeze
    -- the preexisting reference so a trigger cannot silently replace it.
    SELECT COALESCE(correction_ref, 'chip_ledger ' || v_id::text)
      INTO v_expected_ref FROM public.ca_drift_incidents
      WHERE id = p_incident_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'correction_incident_missing'; END IF;
    UPDATE public.ca_drift_incidents
       SET correction_ref = COALESCE(correction_ref, 'chip_ledger ' || v_id::text)
     WHERE id = p_incident_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'correction_incident_update_missing'; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.ca_drift_incidents
      WHERE id = p_incident_id AND correction_ref IS NOT DISTINCT FROM v_expected_ref) THEN
      RAISE EXCEPTION 'correction_incident_reference_mismatch';
    END IF;
    v_event_detail := jsonb_build_object('correction_posted', v_id, 'amount', p_amount,
                                        'from', p_from_type, 'to', p_to_type);
    INSERT INTO public.ca_incident_events (incident_id, kind, actor, detail)
    VALUES (p_incident_id, 'repair_action', v_uid, v_event_detail)
    RETURNING id INTO v_event_id;
    IF v_event_id IS NULL THEN RAISE EXCEPTION 'correction_incident_event_missing'; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.ca_incident_events
      WHERE id = v_event_id AND incident_id = p_incident_id
        AND kind = 'repair_action' AND actor IS NOT DISTINCT FROM v_uid
        AND detail IS NOT DISTINCT FROM v_event_detail) THEN
      RAISE EXCEPTION 'correction_incident_event_mismatch';
    END IF;
  END IF;

  -- Same transaction as the original ledger, overlays, documents and incident.
  -- A duplicate/failed/suppressed intent insert must never commit uncovered work.
  IF v_id IS NULL THEN RAISE EXCEPTION 'correction_ledger_insert_missing'; END IF;
  INSERT INTO public.ca_correction_request_intents_v1(linkage_key, ledger_id, request_intent)
    VALUES (v_key, v_id, v_intent);
  IF NOT FOUND THEN RAISE EXCEPTION 'correction_intent_insert_missing'; END IF;

  IF NOT EXISTS (SELECT 1 FROM public.ca_correction_request_intents_v1
    WHERE linkage_key = v_key AND ledger_id = v_id
      AND request_intent IS NOT DISTINCT FROM v_intent) THEN
    RAISE EXCEPTION 'correction_intent_retained_mismatch';
  END IF;

  RETURN jsonb_build_object('ok', true, 'replayed', false, 'ledger_id', v_id);
END $function$;
-- END exact owner successor-definition.sql.

-- Post-install metadata checks stay inside the same activation transaction.
-- They invoke no financial function and create no historical request intent.
DO $installed$ DECLARE target oid;actual jsonb;who text;priv text;BEGIN
 target:='public.fn_ca_post_correction(text,uuid,text,uuid,numeric,text,uuid,bigint,uuid,uuid,jsonb)'::regprocedure;
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=target AND proowner='postgres'::regrole AND prokind='f'
  AND prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql') AND prosecdef AND NOT proretset
  AND NOT proisstrict AND NOT proleakproof AND provolatile='v' AND proparallel='u'
  AND pronargs=11 AND pronargdefaults=5 AND prorettype='jsonb'::regtype
  AND proconfig=ARRAY['search_path=public']::text[]
  AND md5(prosrc)='d1b4797078edc5a08f63fc438d914cbb'
  AND pg_get_function_arguments(oid)=$arguments$p_from_type text, p_from_entity uuid, p_to_type text, p_to_entity uuid, p_amount numeric, p_reason text, p_incident_id uuid DEFAULT NULL::uuid, p_write_failure_id bigint DEFAULT NULL::bigint, p_club_id uuid DEFAULT NULL::uuid, p_union_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb$arguments$)
 THEN RAISE EXCEPTION 'correction_writer_installed_contract_mismatch' USING DETAIL='public.fn_ca_post_correction';END IF;
 SELECT jsonb_agg(a::text ORDER BY a::text) INTO actual FROM pg_proc p,LATERAL unnest(p.proacl)a WHERE p.oid=target;
 IF actual IS DISTINCT FROM '["postgres=X/postgres","service_role=X/postgres"]'::jsonb
  OR has_function_privilege('anon',target,'EXECUTE') OR has_function_privilege('authenticated',target,'EXECUTE')
  OR NOT has_function_privilege('service_role',target,'EXECUTE')
 THEN RAISE EXCEPTION 'correction_writer_installed_contract_mismatch' USING DETAIL='public.fn_ca_post_correction ACL';END IF;
 target:='public.ca_correction_request_intents_v1'::regclass;
 IF NOT EXISTS(SELECT 1 FROM pg_class WHERE oid=target AND relkind='r' AND relowner='postgres'::regrole
  AND relrowsecurity AND NOT relforcerowsecurity AND NOT relispartition AND relreplident='d' AND reloptions IS NULL)
  OR EXISTS(SELECT 1 FROM pg_inherits WHERE target IN(inhparent,inhrelid))
  OR EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=target)
 THEN RAISE EXCEPTION 'correction_writer_installed_contract_mismatch' USING DETAIL='public.ca_correction_request_intents_v1';END IF;
 SELECT jsonb_agg(jsonb_build_object('name',a.attname,'ordinal',a.attnum,'type',format_type(a.atttypid,a.atttypmod),
  'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity,'generated',a.attgenerated,'acl',a.attacl) ORDER BY a.attnum)
 INTO actual FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
 WHERE a.attrelid=target AND a.attnum>0 AND NOT a.attisdropped;
 IF actual IS DISTINCT FROM $columns$[
 {"name":"linkage_key","ordinal":1,"type":"text","not_null":true,"default":null,"identity":"","generated":"","acl":null},
 {"name":"ledger_id","ordinal":2,"type":"uuid","not_null":true,"default":null,"identity":"","generated":"","acl":null},
 {"name":"request_intent","ordinal":3,"type":"jsonb","not_null":true,"default":null,"identity":"","generated":"","acl":null},
 {"name":"recorded_at","ordinal":4,"type":"timestamp with time zone","not_null":true,"default":"clock_timestamp()","identity":"","generated":"","acl":null}]
 $columns$::jsonb THEN RAISE EXCEPTION 'correction_writer_installed_contract_mismatch' USING DETAIL='private intent columns';END IF;
 SELECT jsonb_agg(a::text ORDER BY a::text) INTO actual FROM pg_class c,LATERAL unnest(c.relacl)a WHERE c.oid=target;
 IF actual IS DISTINCT FROM '["postgres=arwdDxtm/postgres"]'::jsonb
 THEN RAISE EXCEPTION 'correction_writer_installed_contract_mismatch' USING DETAIL='private intent ACL';END IF;
 FOREACH who IN ARRAY ARRAY['anon','authenticated','service_role'] LOOP
  FOREACH priv IN ARRAY ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER','MAINTAIN'] LOOP
   IF has_table_privilege(who,target,priv) THEN RAISE EXCEPTION 'correction_writer_installed_contract_mismatch' USING DETAIL=who||' private intent '||priv;END IF;
  END LOOP;
  FOREACH priv IN ARRAY ARRAY['SELECT','INSERT','UPDATE','REFERENCES'] LOOP
   IF has_any_column_privilege(who,target,priv) THEN RAISE EXCEPTION 'correction_writer_installed_contract_mismatch' USING DETAIL=who||' private intent column '||priv;END IF;
  END LOOP;
 END LOOP;
 IF (SELECT count(*) FROM pg_constraint WHERE conrelid=target)<>3
  OR NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid=target AND contype='p' AND conkey=ARRAY[1]::smallint[] AND convalidated AND NOT condeferrable)
  OR NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid=target AND contype='u' AND conkey=ARRAY[2]::smallint[] AND convalidated AND NOT condeferrable)
  OR NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid=target AND contype='c' AND conkey=ARRAY[3]::smallint[] AND convalidated AND NOT condeferrable
    AND regexp_replace(pg_get_expr(conbin,conrelid),'[[:space:]()]','','g')=$check$jsonb_typeofrequest_intent='object'::textANDrequest_intent->>'version'::text='1'::text$check$)
 THEN RAISE EXCEPTION 'correction_writer_installed_contract_mismatch' USING DETAIL='private intent constraints';END IF;
 IF (SELECT count(*) FROM pg_index WHERE indrelid=target)<>2
  OR EXISTS(SELECT 1 FROM pg_index WHERE indrelid=target AND (NOT indisunique OR NOT indisvalid OR NOT indisready OR NOT indislive OR NOT indimmediate))
 THEN RAISE EXCEPTION 'correction_writer_installed_contract_mismatch' USING DETAIL='private intent indexes';END IF;
 IF (SELECT count(*) FROM pg_trigger WHERE tgrelid=target)<>1
  OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=target AND tgname='ca_correction_intent_immutable_v1'
   AND tgtype=58 AND tgenabled='O' AND NOT tgisinternal AND NOT tgdeferrable AND NOT tginitdeferred
   AND tgfoid='public.ca_correction_intent_immutable_v1()'::regprocedure AND tgnargs=0 AND tgqual IS NULL)
 THEN RAISE EXCEPTION 'correction_writer_installed_contract_mismatch' USING DETAIL='private intent trigger';END IF;
 IF EXISTS(SELECT 1 FROM public.ca_correction_request_intents_v1)
 THEN RAISE EXCEPTION 'correction_writer_installed_contract_mismatch' USING DETAIL='unexpected historical intent rows';END IF;
 target:='public.ca_correction_intent_immutable_v1()'::regprocedure;
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=target AND proowner='postgres'::regrole AND prokind='f'
  AND prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql') AND NOT prosecdef AND NOT proretset
  AND NOT proisstrict AND NOT proleakproof AND provolatile='v' AND proparallel='u'
  AND pronargs=0 AND prorettype='trigger'::regtype AND proconfig=ARRAY['search_path=pg_catalog']::text[]
  AND md5(prosrc)='bf0001908ba6c79158c6a444f1d006c6')
 THEN RAISE EXCEPTION 'correction_writer_installed_contract_mismatch' USING DETAIL='public.ca_correction_intent_immutable_v1';END IF;
 SELECT jsonb_agg(a::text ORDER BY a::text) INTO actual FROM pg_proc p,LATERAL unnest(p.proacl)a WHERE p.oid=target;
 IF actual IS DISTINCT FROM '["postgres=X/postgres"]'::jsonb
  OR has_function_privilege('anon',target,'EXECUTE') OR has_function_privilege('authenticated',target,'EXECUTE')
  OR has_function_privilege('service_role',target,'EXECUTE')
 THEN RAISE EXCEPTION 'correction_writer_installed_contract_mismatch' USING DETAIL='immutable intent function ACL';END IF;
END $installed$;
COMMIT;
